import React, { act } from "react";
import { createRoot } from "react-dom/client";
import api from "../../lib/api";
import * as auth from "../../context/AuthContext";
import GoogleMerchantObservationSelector from "./GoogleMerchantObservationSelector";

jest.mock("../../lib/api", () => ({ __esModule: true, default: {
    get: jest.fn(), post: jest.fn(), put: jest.fn(), delete: jest.fn(), request: jest.fn(),
} }));

const USER = { id: "synthetic-owner", role: "owner" };
// Actual local backend response generated by choices.call(local_db()).
const CHOICES = {
    source: "mezan_google_local_membership", owner_id: USER.id,
    observation_id: "4516b385-8b53-4cf5-b132-0c3a21c06a3a", observed_at: "2026-10-29T22:44:25.647604+00:00",
    local_membership: "matching_complete_bracketing_snapshots", local_set_complete: true, local_account_count: 2,
    ads_accounts: [{ account_id: "5052346701", display_name: "إعلانات المتجر" }],
    merchant_accounts: [{ merchant_id: "123", display_name: "كتالوج المتجر" }],
    remote_account_set_complete: false, native_link_verified: false, merchant_access_verified: false,
    continuous_authorization_proved: false, store_product_mapping_verified: false, ads_eligibility_verified: false,
    execution_authorized: false, provider_calls: 0, provider_writes: 0,
};
function body() { return JSON.parse(JSON.stringify(CHOICES)); }
// Actual699 route/helper/observer output with synthetic provider products:[] on2026-10-29.
const EMPTY_OBSERVED = {
    scope: { owner_id: USER.id, ads_customer_id: "5052346701", merchant_id: "123" }, products: [],
    started_at: "2026-10-29T22:46:30.415265+00:00", observed_at: "2026-10-29T22:46:30.417756+00:00",
    semantic_digest: "022f86a32757b5361f87048c0fcee499403bd1585a98c8bb5dab0e048a310742", pages_read: 1,
    source: "merchant_processed_products_v1", complete: true, atomic_snapshot: false, mapping_status: "unverified",
    store_product_mapping_verified: false, google_ads_channel_verified: false, destination_verified: false,
    category_membership_verified: false, attribution_verified: false, execution_authorized: false, provider_writes: 0,
    access_observation: { ads_customer_id: "5052346701", merchant_id: "123",
        credential_evidence_id: "google-bound-read-c7a39171be8a400b82cb56e1653a2020", native_link_resource: "customers/5052346701/productLinks/17",
        local_membership: "matching_bracketing_snapshots", native_link_set: "matching_complete_bracketing_reads",
        checked_at: "2026-10-29T22:46:30.418450+00:00", continuous_authorization_proved: false },
};
function pending() { let resolve, reject; const promise = new Promise((ok, bad) => { resolve = ok; reject = bad; }); return { promise, resolve, reject }; }
let container, root, currentAuth, authSpy;
beforeEach(() => {
    globalThis.IS_REACT_ACT_ENVIRONMENT = true;
    jest.clearAllMocks(); api.get.mockReset(); api.get.mockResolvedValue({ data: body() });
    currentAuth = { user: USER, authStatus: "authenticated", loading: false, refreshUser: jest.fn() };
    authSpy = jest.spyOn(auth, "useAuth").mockImplementation(() => currentAuth);
    container = document.createElement("div"); document.body.appendChild(container); root = createRoot(container);
});
afterEach(async () => { await act(async () => root.unmount()); authSpy.mockRestore(); container.remove(); });
async function render() { await act(async () => root.render(<GoogleMerchantObservationSelector />)); }
function button(label) { return [...container.querySelectorAll("button")].find((element) => element.textContent === label); }
async function click(label = "تحديث قائمة الحسابات") { await act(async () => button(label).click()); }
async function choose(label, value) {
    const select = container.querySelector(`select[aria-label="${label}"]`);
    await act(async () => { select.value = value; select.dispatchEvent(new Event("change", { bubbles: true })); });
}
async function selected() { await choose("حساب إعلانات Google", "5052346701"); await choose("حساب Merchant Center", "123"); }
function noWrites() { for (const method of ["post", "put", "delete", "request"]) expect(api[method]).not.toHaveBeenCalled(); }

test("mount and explicit options cause no automatic reads; single account has no default", async () => {
    await render(); expect(api.get).not.toHaveBeenCalled();
    await click(); expect(api.get).toHaveBeenCalledTimes(1);
    expect([...container.querySelectorAll("select")].map((row) => row.value)).toEqual(["", ""]);
    expect(container.textContent).toContain("5052346701"); expect(container.textContent).toContain("123");
    expect(container.textContent).toContain("ليست حصرًا"); expect(button("قراءة منتجات Merchant Center")).toBeUndefined();
    await selected(); expect(api.get).toHaveBeenCalledTimes(1);
    expect(button("قراءة منتجات Merchant Center")).toBeDefined(); noWrites();
});
test("unchanged child reads only exact explicit IDs when its separate button is clicked", async () => {
    await render(); await click(); await selected();
    api.get.mockRejectedValueOnce({ response: { status: 409 }, message: "PRIVATE_PROVIDER" });
    await click("قراءة منتجات Merchant Center");
    expect(api.get).toHaveBeenCalledTimes(2);
    expect(api.get.mock.calls[1][0]).toBe("/integrations-v2/google_ads/merchant-products/observation");
    expect(api.get.mock.calls[1][1].params).toEqual({ account_id: "5052346701", merchant_id: "123" });
    expect(container.textContent).not.toContain("PRIVATE_PROVIDER"); noWrites();
});
test("actual complete backend observation appears after two separate explicit actions and clears on new choice", async () => {
    const list = body(); list.merchant_accounts.push({ merchant_id: "456", display_name: "حساب ثان" }); list.local_account_count++;
    api.get.mockResolvedValueOnce({ data: list }); await render(); await click(); await selected();
    api.get.mockResolvedValueOnce({ data: EMPTY_OBSERVED }); await click("قراءة منتجات Merchant Center");
    expect(container.textContent).toContain("لم تُرجع القراءة منتجات");
    expect(container.textContent).toContain("لا يثبت ذلك خلو متجر سلة");
    await choose("حساب Merchant Center", "456");
    expect(container.textContent).not.toContain("لم تُرجع القراءة منتجات");
    expect(api.get).toHaveBeenCalledTimes(2); noWrites();
});
test("refresh clears even unchanged explicit choices and unmounts an inflight child", async () => {
    await render(); await click(); await selected();
    const oldRead = pending(); api.get.mockReturnValueOnce(oldRead.promise);
    await click("قراءة منتجات Merchant Center"); const oldSignal = api.get.mock.calls[1][1].signal;
    await click(); expect(oldSignal.aborted).toBe(true);
    expect([...container.querySelectorAll("select")].map((row) => row.value)).toEqual(["", ""]);
    expect(button("قراءة منتجات Merchant Center")).toBeUndefined();
    await act(async () => oldRead.resolve({ data: { products: [{ offer_id: "PRIVATE_OLD" }] } }));
    expect(container.textContent).not.toContain("PRIVATE_OLD"); noWrites();
});
test.each(["checking", "unavailable", "anonymous"])("authStatus %s hides retained owner and cancels list", async (status) => {
    const inflight = pending(); api.get.mockReturnValueOnce(inflight.promise);
    await render(); await click(); const signal = api.get.mock.calls[0][1].signal;
    currentAuth = { ...currentAuth, authStatus: status }; await render();
    expect(container.textContent).toBe(""); expect(signal.aborted).toBe(true);
    await act(async () => inflight.resolve({ data: body() })); expect(container.textContent).toBe("");
    expect(currentAuth.refreshUser).not.toHaveBeenCalled();
});
test.each([{ ...USER, role: "viewer", is_owner: true }, { ...USER, disabled: true }, { ...USER, is_active: false },
    { ...USER, deleted_at: "today" }, { ...USER, id: null }, false])("non-owner or invalid auth shape does not request choices (%j)", async (user) => {
    currentAuth = { ...currentAuth, user }; await render(); expect(container.textContent).toBe(""); expect(api.get).not.toHaveBeenCalled();
});
test("owner change rejects late old list and requires fresh explicit selection", async () => {
    const old = pending(); api.get.mockReturnValueOnce(old.promise); await render(); await click();
    currentAuth = { ...currentAuth, user: { ...USER, id: "second-owner" } }; await render();
    expect(container.querySelectorAll("select")).toHaveLength(0);
    await act(async () => old.resolve({ data: body() })); expect(container.querySelectorAll("select")).toHaveLength(0);
    const next = body(); next.owner_id = "second-owner"; api.get.mockResolvedValueOnce({ data: next });
    await click(); expect([...container.querySelectorAll("select")].every((row) => row.value === "")).toBe(true);
});
test("cancelled old success cannot overwrite a later list or clear its busy state", async () => {
    const old = pending(), next = pending(); api.get.mockReturnValueOnce(old.promise).mockReturnValueOnce(next.promise);
    await render(); await click(); await click("إلغاء تحديث القائمة"); await click();
    await act(async () => old.resolve({ data: body() }));
    expect(button("تحديث قائمة الحسابات").disabled).toBe(true); expect(container.querySelectorAll("select")).toHaveLength(0);
    const data = body(); data.ads_accounts[0].display_name = "القائمة الحالية";
    await act(async () => next.resolve({ data }));
    expect(container.textContent).toContain("القائمة الحالية"); expect(button("تحديث قائمة الحسابات").disabled).toBe(false);
});
test.each([401, 403, 409, 500])("failed manual refresh%s removes stale choices and keeps raw errors private", async (status) => {
    await render(); await click(); await selected();
    api.get.mockRejectedValueOnce({ response: { status, data: { secret: "PRIVATE_ERROR" } }, message: "PRIVATE_ERROR" });
    await click(); expect(container.querySelectorAll("select")).toHaveLength(0);
    expect(container.textContent).not.toContain("PRIVATE_ERROR"); expect(container.querySelector('[role="alert"]')).not.toBeNull();
    expect(currentAuth.refreshUser).not.toHaveBeenCalled(); noWrites();
});
test("empty local list states its scope without inventing missing remote accounts", async () => {
    const data = body(); data.ads_accounts = []; data.merchant_accounts = []; data.local_account_count = 0;
    api.get.mockResolvedValueOnce({ data }); await render(); await click();
    expect(container.textContent).toContain("هذا لا يعني عدم وجود حسابات");
    expect(button("قراءة منتجات Merchant Center")).toBeUndefined(); noWrites();
});
test("labels remain inert and a URL/workspace-like input does not adopt an account", async () => {
    window.history.replaceState({}, "", "/?account_id=5052346701&merchant_id=123");
    const data = body(); data.ads_accounts[0].display_name = "https://example.invalid/<img src=x>";
    api.get.mockResolvedValueOnce({ data }); await render(); await click();
    expect(container.querySelectorAll("img,a,iframe")).toHaveLength(0);
    expect([...container.querySelectorAll("select")].map((row) => row.value)).toEqual(["", ""]);
    window.history.replaceState({}, "", "/"); noWrites();
});
test("actual AuthProvider current-user bootstrap supplies owner identity without automatic choice reads", async () => {
    authSpy.mockRestore(); api.get.mockResolvedValueOnce({ data: USER });
    await act(async () => root.render(<auth.AuthProvider><GoogleMerchantObservationSelector /></auth.AuthProvider>));
    expect(api.get.mock.calls.map((args) => args[0])).toEqual(["/auth/me"]);
    expect(button("تحديث قائمة الحسابات")).toBeDefined();
    api.get.mockResolvedValueOnce({ data: body() }); await click();
    expect(api.get.mock.calls[1][0]).toBe("/integrations-v2/google_ads/merchant-products/choices"); noWrites();
});
